                <td data-testid="statement-invoice-dueDate">{i.dueDate}</td>
                <td data-testid="statement-invoice-status">{invoiceStatus(i)}</td>
              </tr>
            ))}
            <tr>
              <td>Job subtotal</td>
              <td data-testid="statement-project-subtotal">{money(group.subtotal)}</td>
            </tr>
          </tbody>
        ))}
        <tfoot>
