            <th>Issued</th>
            <th>Due</th>
            <th>Amount owed</th>
          </tr>
        </thead>
        <tbody>
          {invoices.map((i) => (
            <tr key={i.id} data-testid={`statement-print-row-${i.id}`}>
              <td>{i.id}</td>
              <td>{i.issuedDate}</td>
              <td>{i.dueDate}</td>
              <td data-testid={`statement-print-amount-${i.id}`}>{money(Number(i.amountDue))}</td>
